css:
.loader { display: inline-flex; align-items: center; justify-content: center; gap: calc(var(--loader-size) * .06); width: var(--loader-size); }
.loader span { width: calc(var(--loader-size) * .16); height: calc(var(--loader-size) * .16); border-radius: calc(var(--loader-size) * .05); background: var(--loader-color); animation: twCrumb calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader i { width: calc(var(--loader-size) * .07); height: calc(var(--loader-size) * .07); border-top: calc(var(--loader-size) * .022) solid color-mix(in srgb, var(--loader-color) 55%, transparent); border-right: calc(var(--loader-size) * .022) solid color-mix(in srgb, var(--loader-color) 55%, transparent); transform: rotate(45deg); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .25); }
.loader span:nth-child(5) { animation-delay: calc(var(--loader-speed) * .5); }
@keyframes twCrumb { 0%, 100% { opacity: .3; transform: rotate(0deg) scale(.78); } 50% { opacity: 1; transform: rotate(45deg) scale(1); } }
